(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  const s = window.__toolboxStore;

  // ① 先回工具箱首页（上一步可能停在元件库）
  document.querySelector('.lib-crumb-link')?.click();
  await sleep(1600);
  const cards = [...document.querySelectorAll('.tb-project-main')];
  out.cardCount = cards.length;
  const card = cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0];
  out.work = (card?.innerText || '').split('\n')[0];
  card?.click();
  await sleep(3200);

  // ② 展开「＋ 添加元件」→ 点「从元件库选」
  [...document.querySelectorAll('.pj-link-btn')].find((b) => b.textContent.includes('添加元件'))?.click();
  await sleep(700);
  const pickBtn = [...document.querySelectorAll('.pj-btn')].find((b) => b.textContent.trim() === '从元件库选');
  out.pickerButton = !!pickBtn;
  pickBtn?.click();
  await sleep(1600);
  out.pickerOpen = !!document.querySelector('.lp-modal');
  out.pickerItems = [...document.querySelectorAll('.lp-item')].map((b) => (b.textContent || '').trim().split('\n')[0]);

  // ③ 挑自建的元件
  const target = [...document.querySelectorAll('.lp-item')].find((b) => (b.textContent || '').includes('土壤湿度')) || document.querySelector('.lp-item');
  out.picked = (target?.textContent || '').trim().split('\n')[0];
  target?.click();
  await sleep(900);
  out.pickerClosed = !document.querySelector('.lp-modal');
  out.formAfterPick = [...document.querySelectorAll('.pj-edit-cell input')].map((i) => i.value).filter(Boolean);

  // ④ 加入作品
  [...document.querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '加入作品')?.click();
  await sleep(2200);
  out.toast = document.querySelector('.pj-toast')?.textContent || null;

  const projects = await s.listProjects();
  const p = projects.find((x) => x.name === out.work) || projects[0];
  const bundle = await s.getProject(p.id);
  out.rowCount = bundle.components.length;
  out.lastRow = bundle.components.slice(-1).map((c) => ({ name: c.name, libraryId: c.libraryId || null }));
  return JSON.stringify(out);
})()
